package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface InboxJpaRepository extends JpaRepository<InboxJpaEntity,UUID>{@Modifying @Query(value="insert into inventory_inbox(event_id,event_type,received_at) values (:id,:type,now()) on conflict(event_id) do nothing",nativeQuery=true)int insertIfAbsent(@Param("id")UUID id,@Param("type")String type);}
